override fun propagateUnresolvedCallFact(
    factAp: FinalFactAp,
    addCallToReturn: (FinalFactReader, FinalFactAp, TraceInfo?) -> Unit,
    addSideEffectRequirement: (FinalFactReader) -> Unit
) {
    val factReader = FinalFactReader(factAp, apManager)

    unresolvedCallDefaultFactPropagation(factAp, addCallToReturn)

    val method = callExpr.callee
    JIRMethodCallFactMapper.mapMethodCallToStartFlowFact(
        statement,
        callee = method,
        callExpr = callExpr,
        returnValue = null,
        factAp = factAp,
        checker = analysisContext.factTypeChecker
    ) { callerFact, startFactBase ->
        val passFactReader = FinalFactReader(callerFact.rebase(startFactBase), apManager)

        val conditionEvaluator = TaintFactAwareConditionEvaluator(
            listOf(passFactReader),
            markAfterAnyAccessorResolver = null // we don't expect such marks in pass rules
        )

        val passEvaluator = TaintPassActionEvaluator(
            apManager, analysisContext.factTypeChecker, passFactReader, typeResolver
        )

        val passRules = taintCtx.passRulesForCallStatement(statement, callExpr, returnValue, passFactReader.factAp)
        var passThroughFacts = applyPassThrough(passRules, conditionEvaluator, passEvaluator)

        if (startFactBase !is AccessPathBase.ClassStatic) {
            analysisContext.taint.externalMethodTracker?.let { tracker ->
                if (JIRCallResolver.alwaysIgnoreMethod(method)) return@let

                val methodName = "${method.enclosingClass.name}#${method.name}"
                val methodDesc = method.description
                val factPosition = startFactBase.toString()
                val ruleApplied = startFactBase in passEvaluator.relevantPositionBase
                tracker.trackExternalMethod(methodName, methodDesc, factPosition, ruleApplied)
            }
        }

        analysisContext.analysisManager.params.defaultGetModel?.run {
            /*todo: fix owasp, propagate default only if  passThroughFacts.isNone */
            val defaultRules = defaultPropagationRules(method)
            val defaultPass = applyPassThrough(defaultRules, conditionEvaluator, passEvaluator)
            passThroughFacts = passThroughFacts.merge(defaultPass)
        }

        passThroughFacts.onSome { evaluatedPass ->
            evaluatedPass.forEach { evp ->
                val rewrittenFacts = summaryRewriter.rewriteSummaryFact(evp.fact)
                for ((unrefinedFact, factRefinement) in rewrittenFacts) {
                    val fact = factRefinement.refineFact(unrefinedFact)
                    passFactReader.updateRefinement(factRefinement)

                    val mappedFact = fact.mapExitToReturnFact() ?: continue

                    val trace = TraceInfo.Rule(evp.rule, evp.action)

                    mappedFact.forEachFactWithAliases(factAp) {
                        addCallToReturn(passFactReader, it, trace)
                    }
                }
            }
        }

        factReader.updateRefinement(passFactReader)
    }

    if (factReader.hasRefinement) {
        addSideEffectRequirement(factReader)
    }
}

private fun unresolvedCallDefaultFactPropagation(
    factAp: FinalFactAp,
    addCallToReturn: (FinalFactReader, FinalFactAp, TraceInfo?) -> Unit,
) {
    val rewrittenFacts = summaryRewriter.rewriteSummaryFact(factAp)
    for ((unrefinedFact, factRefinement) in rewrittenFacts) {
        val fact = factRefinement.refineFact(unrefinedFact)
        addCallToReturn(factRefinement, fact, null)
    }
}

    private val userRuleDefinedActions: Map<AccessPathBase, Map<String, List<UserRuleDefinedAction>>> by lazy {
        val result = hashMapOf<AccessPathBase, MutableMap<String, MutableList<UserRuleDefinedAction>>>()

        fun indexRule(rule: TaintConfigurationItem, positions: Set<Position>, marks: Set<String>) {
            positions.groupBy { it.resolveBaseAp() }.forEach { (base, basePositions) ->
                val actionsByMark = result.computeIfAbsent(base) { hashMapOf() }
                val action = UserRuleDefinedAction(rule, basePositions.toSet())
                marks.forEach { mark ->
                    actionsByMark.computeIfAbsent(mark) { mutableListOf() }.add(action)
                }
            }
        }

        for (sourceRule in taintCtx.allRelevantSourceRulesForCallStatement(statement)) {
            val ruleInfo = sourceRule.info as? UserDefinedRuleInfo ?: continue

            val simplifiedCondition = conditionRewriter.rewrite(sourceRule.condition)
            if (simplifiedCondition.isFalse) continue

            val positions = sourceRule.actionsAfter.mapTo(hashSetOf()) { it.position }
            indexRule(sourceRule, positions, ruleInfo.relevantTaintMarks)
        }

        for (cleanRule in taintCtx.allRelevantCleanRulesForCallStatement(statement)) {
            val ruleInfo = cleanRule.info as? UserDefinedRuleInfo ?: continue

            val simplifiedCondition = conditionRewriter.rewrite(cleanRule.condition)
            if (simplifiedCondition.isFalse) continue

            val positions = cleanRule.actionsAfter.filterIsInstance<RemoveMark>().mapTo(hashSetOf()) { it.position }
            indexRule(cleanRule, positions, ruleInfo.relevantTaintMarks)
        }

        result
    }

    fun rewriteSummaryFact(fact: FinalFactAp): List<Pair<FinalFactAp, FinalFactReader>> {
        val startFactReader = FinalFactReader(fact, apManager)
        val actionsForBase = userRuleDefinedActions[fact.base].orEmpty()
        if (actionsForBase.isEmpty()) return listOf(fact to startFactReader)

        val cleanEvaluator = JIRTaintCleanActionEvaluator(typeResolver)
        val cleanedFact = actionsForBase.entries.applyCleanerActions(
            initial = EvaluatedCleanAction.initial(startFactReader)
        ) { (mark, actions), current ->
            actions.applyCleanerActions(
                evaluator = cleanEvaluator,
                itemRule = { it.rule },
                itemActions = { ruleDefinedAction ->
                    val taintMark = TaintMark(mark)
                    ruleDefinedAction.positions.map {
                        RemoveMark(taintMark, it, TaintCleanReach.Exact)
                    }
                },
                initial = current
            )
        }

        return cleanedFact.mapNotNull {
            val resultFact = it.fact ?: return@mapNotNull null
            resultFact.factAp to resultFact
        }
    }
